from pathlib import Path
import json,hashlib,subprocess,os,signal,datetime,time
root=Path.cwd();out=root/'.local/gap-uid-binding-01'
base=json.loads((root/'.local/fidelity-checkpoints/required-04/source-after.json').read_text())
paths=list(base)+['.local/gap-uid-binding-01/probe.gd','.local/gap-uid-binding-01/runner.py']
def inventory():return {n:{'sha256':hashlib.sha256((root/n).read_bytes()).hexdigest(),'bytes':(root/n).stat().st_size}for n in paths}
before=inventory();(out/'source-before.json').write_text(json.dumps(before,indent=2)+'\n')
for n in ['data','cache','config']:(out/'xdg'/n).mkdir(parents=True,exist_ok=True)
env=os.environ.copy();env.update({f'XDG_{n.upper()}_HOME':str(out/'xdg'/n)for n in ['data','cache','config']})
started=datetime.datetime.now(datetime.timezone.utc).isoformat();start=time.monotonic()
cmd=['godot','--headless','--audio-driver','Dummy','--path',str(root),'--script',str(out/'probe.gd')]
with (out/'native.log').open('w')as f:
 child=subprocess.Popen(cmd,env=env,stdout=f,stderr=subprocess.STDOUT,start_new_session=True)
 try:code=child.wait(timeout=20)
 except subprocess.TimeoutExpired:os.killpg(child.pid,signal.SIGTERM);child.wait(timeout=3);code=124
after=inventory();(out/'source-after.json').write_text(json.dumps(after,indent=2)+'\n');log=(out/'native.log').read_text()
receipt={'started_utc':started,'finished_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'deadline_seconds':20,'elapsed_seconds':time.monotonic()-start,'command':cmd,'pid':child.pid,'exit_code':code,'source_count':len(before),'source_unchanged':before==after,'pass_lines':sum(x.startswith('PASS:')for x in log.splitlines()),'raw_errors':[x for x in log.splitlines()if any(t in x for t in ['ERROR:','SCRIPT ERROR:','FAIL:'])],'scope':'Native canonical UID/source/registry binding only. Qualifies five sidecars generated by required04 editor import; does not rewrite its raw eligible=false receipt or rerun its6697 assertions.'}
receipt['eligible']=code==0 and before==after and receipt['pass_lines']==15 and not receipt['raw_errors']
(out/'receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt,indent=2));raise SystemExit(0 if receipt['eligible']else 1)
